module gx4000_dma_engine(input logic clk16,input logic rst_n,input logic page_enable,input logic [15:0] cpu_addr,input logic cpu_read,input logic cpu_write,input logic [7:0] cpu_wdata,output logic cpu_hit,output logic [7:0] cpu_rdata,input logic hsync,input logic raster_irq_pending,output logic [15:0] ram_addr,input logic [7:0] ram_rdata,output logic [2:0] dma_irq_pending,output logic dma_irq_any,output logic psg_write,output logic [3:0] psg_reg,output logic [7:0] psg_data);
logic [15:0] sar[0:2];logic [7:0] ppr[0:2];logic [11:0] pause_count[0:2];logic [7:0] prescale_count[0:2];logic [11:0] loop_count[0:2];logic [15:0] loop_addr[0:2];logic [2:0] enabled;logic hsync_d;wire hsync_rise=hsync&&!hsync_d;wire dma_reg_sel=page_enable&&(cpu_addr>=16'h6c00)&&(cpu_addr<=16'h6c0f);assign cpu_hit=dma_reg_sel;assign dma_irq_any=|dma_irq_pending;always_comb begin cpu_rdata=8'hff;if(dma_reg_sel&&cpu_read)cpu_rdata={raster_irq_pending,dma_irq_pending[0],dma_irq_pending[1],dma_irq_pending[2],1'b0,enabled[2],enabled[1],enabled[0]};end
typedef enum logic[3:0]{ST_IDLE,ST_SELECT,ST_WAIT_LO,ST_CAPTURE_LO,ST_WAIT_HI,ST_CAPTURE_HI,ST_EXEC,ST_EXEC_DELAY}state_t;state_t state;logic [1:0] channel;wire [15:0] current_next_sar={sar[channel][15:1],1'b0}+16'd2;logic [7:0] instr_lo,instr_hi,exec_delay;wire [15:0] instruction={instr_hi,instr_lo};integer i;
always_ff @(posedge clk16 or negedge rst_n)begin if(!rst_n)begin hsync_d<=0;enabled<=0;dma_irq_pending<=0;ram_addr<=0;psg_write<=0;psg_reg<=0;psg_data<=0;state<=ST_IDLE;channel<=0;instr_lo<=0;instr_hi<=0;exec_delay<=0;for(i=0;i<3;i=i+1)begin sar[i]<=0;ppr[i]<=0;pause_count[i]<=0;prescale_count[i]<=0;loop_count[i]<=0;loop_addr[i]<=0;end end else begin hsync_d<=hsync;psg_write<=0;if(dma_reg_sel&&cpu_write)case(cpu_addr[3:0])0:sar[0][7:0]<=cpu_wdata;1:sar[0][15:8]<=cpu_wdata;2:ppr[0]<=cpu_wdata;4:sar[1][7:0]<=cpu_wdata;5:sar[1][15:8]<=cpu_wdata;6:ppr[1]<=cpu_wdata;8:sar[2][7:0]<=cpu_wdata;9:sar[2][15:8]<=cpu_wdata;10:ppr[2]<=cpu_wdata;15:begin enabled<=cpu_wdata[2:0];if(cpu_wdata[6])dma_irq_pending[0]<=0;if(cpu_wdata[5])dma_irq_pending[1]<=0;if(cpu_wdata[4])dma_irq_pending[2]<=0;end default:;endcase if(hsync_rise)begin for(i=0;i<3;i=i+1)if(pause_count[i]!=0)begin if(prescale_count[i]==0)begin prescale_count[i]<=ppr[i];pause_count[i]<=pause_count[i]-1'b1;end else prescale_count[i]<=prescale_count[i]-1'b1;end if(state==ST_IDLE)begin channel<=0;state<=ST_SELECT;end end case(state)ST_IDLE:;ST_SELECT:begin if(channel>=3)state<=ST_IDLE;else if(enabled[channel]&&(pause_count[channel]==0))begin ram_addr<={sar[channel][15:1],1'b0};state<=ST_WAIT_LO;end else channel<=channel+1'b1;end ST_WAIT_LO:state<=ST_CAPTURE_LO;ST_CAPTURE_LO:begin instr_lo<=ram_rdata;ram_addr<={sar[channel][15:1],1'b0}+1'b1;state<=ST_WAIT_HI;end ST_WAIT_HI:state<=ST_CAPTURE_HI;ST_CAPTURE_HI:begin instr_hi<=ram_rdata;state<=ST_EXEC;end ST_EXEC:begin sar[channel]<=current_next_sar;case(instruction[15:12])0:begin psg_reg<=instruction[11:8];psg_data<=instruction[7:0];psg_write<=1;exec_delay<=127;state<=ST_EXEC_DELAY;end 1:begin if(instruction[11:0]!=0)begin pause_count[channel]<=instruction[11:0];prescale_count[channel]<=ppr[channel];end exec_delay<=15;state<=ST_EXEC_DELAY;end 2:begin if(instruction[11:0]!=0)begin loop_count[channel]<=instruction[11:0];loop_addr[channel]<=current_next_sar;end exec_delay<=15;state<=ST_EXEC_DELAY;end 4:begin if(instruction[0]&&loop_count[channel]!=0)begin sar[channel]<=loop_addr[channel];loop_count[channel]<=loop_count[channel]-1'b1;end if(instruction[4])dma_irq_pending[channel]<=1;if(instruction[5])enabled[channel]<=0;exec_delay<=15;state<=ST_EXEC_DELAY;end default:begin exec_delay<=15;state<=ST_EXEC_DELAY;end endcase end ST_EXEC_DELAY:if(exec_delay==0)begin channel<=channel+1'b1;state<=ST_SELECT;end else exec_delay<=exec_delay-1'b1;default:state<=ST_IDLE;endcase end end
endmodule
